def gen(rng):
    def fmt(cs):
        return str(len(cs)) + '\n' + '\n'.join(f'{a} {b}' for a, b in cs)
    tests = [fmt([(1, 1)]), fmt([(5, 3)]), fmt([(2, 2), (2, 4), (2, 6)]), fmt([(3, 4), (2, 5), (4, 9), (1, 2)]),
             fmt([(10**9, 10**9)]), fmt([(10**9, 10**9 - 1)]), fmt([(1, 10**9)] * 3), fmt([(3, 3), (3, 3), (3, 3)]),
             fmt([(2, 3), (2, 3), (1, 3)])]
    for n in (2, 3, 4, 6, 8, 10, 12):
        for (dm, lm) in ((4, 10), (8, 30), (5, 12)):
            tests.append(fmt([(rng.randint(1, dm), rng.randint(1, lm)) for _ in range(n)]))
    N = 100000
    tests.append(fmt([(rng.randint(1, 10**9), rng.randint(1, 10**9)) for _ in range(N)]))
    tests.append(fmt([(rng.randint(1, 10**4), rng.randint(1, 5 * 10**8)) for _ in range(N)]))
    tests.append(fmt([(1, i + 1) for i in range(N)]))
    tests.append(fmt([(rng.randint(1, 10**4), rng.randint(1, 10**4)) for _ in range(5000)]))
    return tests

